const app={user:null,page:'home',feed:'For you',roomId:null,roomSince:0,poll:null,hold:null,lastTap:0,likes:new Set(),profile:null};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
