async function api(url,options={}){const r=await fetch(url,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json',...(options.headers||{})}});const data=await r.json().catch(()=>({}));if(!r.ok)throw Error(data.error||'Something went wrong. Try again.');return data}
const send=(url,body={})=>api(url,{method:'POST',body:JSON.stringify(body)});
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2400)}
function modal(title,body,wide=false){$('#modal-panel').innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="modal-close" aria-label="Close">×</button></div>${body}`;$('#modal-panel').classList.toggle('wide-modal',wide);$('#modal').classList.remove('hidden');$('.modal-close').onclick=closeModal;$('#modal').onclick=e=>{if(e.target===$('#modal')||e.target.classList.contains('modal-scrim'))closeModal()};}
let modalCleanup=null;function closeModal(){if(typeof modalCleanup==='function'){try{modalCleanup()}catch{}modalCleanup=null}$('#modal').classList.add('hidden');$('#modal-panel').classList.remove('wide-modal','fullscreen-modal')}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
function requireLogin(){if(app.user)return true;openAuth('login');return false}
function openAuth(mode='login'){
 const signup=mode==='signup',forgot=mode==='forgot';let stage=mode;
 const title=signup?'Create your account':forgot?'Reset your password':'Welcome back';
 const fields=signup?`<label>Your name<input name="name" required minlength="2" maxlength="40" placeholder="How friends know you"></label><label>Choose a handle<input name="handle" required minlength="3" maxlength="24" pattern="[A-Za-z0-9_.]+" placeholder="yourname"></label><label>Email or mobile number<input name="identifier" required autocomplete="username" placeholder="you@gmail.com or +1…"></label><label>Password<input name="password" required minlength="10" type="password" autocomplete="new-password" placeholder="At least 10 characters"></label><p class="auth-footnote">Test mode: email/SMS verification isn’t enabled yet. Use test contact details.</p>`:forgot?`<p>A local test reset code will appear here. No email or SMS is sent yet.</p><label>Email or mobile number<input name="identifier" required placeholder="Account email or number"></label>`:`<label>Email or mobile number<input name="identifier" required autocomplete="username" placeholder="you@gmail.com or +1…"></label><label>Password<input name="password" required type="password" autocomplete="current-password" placeholder="Your password"></label><button type="button" class="text-btn forgot-trigger">Forgot password?</button>`;
 modal(title,`<div class="auth-mark">t</div><p class="auth-lede">${signup?'A good place to make a little noise.':forgot?'We’ll help you get back into your account.':'Sign in and pick up where you left off.'}</p><form id="auth-form" class="auth-form">${fields}<div id="auth-error" class="form-error"></div><button class="modal-primary auth-submit" type="submit">${signup?'Create account':forgot?'Request reset':'Sign in'}</button></form><button class="google-signin" type="button" data-auth="google"><span>G</span> Continue with Google</button><div class="auth-divider"><span>or</span></div><p class="auth-switch">${signup?'Already have an account?':forgot?'Remembered it?':'New to Trude?'} <button type="button" class="text-btn" data-auth="${signup?'login':forgot?'login':'signup'}">${signup?'Sign in':'Create an account'}</button></p>`,false);
 $('#auth-form').addEventListener('submit',async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(e.currentTarget).entries()),error=$('#auth-error');error.textContent='';try{if(stage==='forgot'){const r=await send('/api/auth/forgot',body);if(!r.resetCode){error.textContent=r.message||'If this account exists, a reset code has been prepared.';return}e.currentTarget.innerHTML=`<input type="hidden" name="identifier" value="${esc(body.identifier)}"><div class="reset-code-display">Local test code <b>${esc(r.resetCode)}</b></div><label>Reset code<input name="code" inputmode="numeric" maxlength="6" required></label><label>New password<input name="password" type="password" minlength="10" autocomplete="new-password" required></label><div id="auth-error" class="form-error"></div><button class="modal-primary auth-submit">Save new password</button>`;stage='reset';return}if(stage==='reset'){await send('/api/auth/reset',body);openAuth('login');toast('Password updated. Sign in again.');return}const result=await send(`/api/auth/${signup?'signup':'login'}`,body);app.user=result.user;closeModal();updateProfile();await loadFeed();toast(signup?'Welcome to Trude ✳':'You’re signed in')}catch(err){error.textContent=err.message}});
 $$('[data-auth]').forEach(b=>b.onclick=()=>b.dataset.auth==='google'?toast('Google sign-in needs OAuth setup. Use email or mobile for this test build.'):openAuth(b.dataset.auth));$('.forgot-trigger')?.addEventListener('click',()=>openAuth('forgot'));
}
