  const tabs=$('.profile-tabs');tabs.innerHTML='<button class="chosen" data-profile-tab="Posts">▦ &nbsp;Posts</button><button data-profile-tab="Liked">♡ &nbsp;Liked</button><button data-profile-tab="Saved">▤ &nbsp;Saved</button><button data-profile-tab="Drafts">▤ &nbsp;Drafts</button><button data-profile-tab="Locked">▣ &nbsp;Locked</button>';
