function audioEditor(draft=null){modal('Make an audio post',`<div class="creator-step"><small>RECORD OR IMPORT</small><p>Make a voice note and listen before you share it.</p><div class="editor-tools"><button class="secondary-btn record-button" id="record-audio">● Start recording</button><button class="secondary-btn" id="stop-audio" disabled>■ Stop</button><label class="secondary-btn file-button">Import audio<input type="file" id="audio-file" accept="audio/*" hidden></label></div><div id="recording-status" class="recording-status"><i></i><span>Ready when you are</span><time>00:00</time></div></div><div id="audio-preview" class="editor-preview"><span>Your audio preview will appear here</span></div><label>Voice style<select id="voice-effect" class="modal-field"><option>Original voice</option><option>Warm room</option><option>Echo preview</option><option>Low pitch preview</option><option>High pitch preview</option></select></label><textarea class="modal-field" id="audio-caption" placeholder="Add a caption"></textarea><div class="editor-tools"><button class="secondary-btn" id="save-audio-draft">Save draft</button><button class="modal-primary" id="publish-audio">Share audio</button></div><p class="auth-footnote">Recording and playback work on this device. Voice styles are preview-only.</p>`,true);let recorder,stream,chunks=[],audioData='',audioType='audio/webm',timer,seconds=0;const ready=()=>{$('#record-audio').disabled=false;$('#record-audio').textContent='● Record again';$('#stop-audio').disabled=true;$('#recording-status').classList.remove('recording');clearInterval(timer)};modalCleanup=()=>{clearInterval(timer);if(recorder?.state==='recording')recorder.stop();stream?.getTracks().forEach(t=>t.stop())};if(draft){$('#audio-caption').value=draft.caption||'';if(draft.mediaData){audioData=draft.mediaData;audioType=draft.mediaType||audioType;$('#audio-preview').innerHTML=`<audio controls src="${audioData}"></audio>`}}$('#record-audio').onclick=async()=>{try{if(!navigator.mediaDevices?.getUserMedia)throw Error();stream=await navigator.mediaDevices.getUserMedia({audio:true});recorder=new MediaRecorder(stream);chunks=[];recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=()=>{const blob=new Blob(chunks,{type:recorder.mimeType||'audio/webm'});audioType=(recorder.mimeType||'audio/webm').split(';')[0];if(blob.size>7*1024*1024){toast('Recording is over 8 MB; record a shorter clip');audioData=''}else{const reader=new FileReader();reader.onload=()=>{audioData=reader.result;$('#audio-preview').innerHTML=`<audio controls src="${URL.createObjectURL(blob)}"></audio>`;$('#recording-status span').textContent='Recording ready · tap play to listen';saveDraft({type:'Audio',title:'Audio recording',caption:$('#audio-caption').value,mediaData:blob.size<700000?audioData:'',mediaType:audioType})};reader.readAsDataURL(blob)}stream?.getTracks().forEach(t=>t.stop());ready()};recorder.start();seconds=0;$('#recording-status').classList.add('recording');$('#recording-status span').textContent='Recording now';$('#record-audio').disabled=true;$('#stop-audio').disabled=false;timer=setInterval(()=>{seconds++;$('#recording-status time').textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`},1000)}catch{toast('Allow microphone access, or use localhost/HTTPS on your phone')}};$('#stop-audio').onclick=()=>{if(recorder?.state==='recording')recorder.stop()};$('#audio-file').onchange=e=>{const f=e.target.files[0];if(!f)return;if(f.size>7*1024*1024)return toast('Choose an audio file under 8 MB');audioType=f.type||'audio/mpeg';const reader=new FileReader();reader.onload=()=>{audioData=reader.result;$('#audio-preview').innerHTML=`<audio controls src="${audioData}"></audio>`;$('#recording-status span').textContent='Audio loaded · tap play to listen'};reader.readAsDataURL(f)};$('#audio-caption').oninput=()=>saveDraft({id:draft?.id,type:'Audio',title:'Audio post',caption:$('#audio-caption').value,mediaData:audioData.length<900000?audioData:'',mediaType:audioType});$('#save-audio-draft').onclick=()=>{saveDraft({id:draft?.id,type:'Audio',title:'Audio post',caption:$('#audio-caption').value,mediaData:audioData.length<900000?audioData:'',mediaType:audioType});closeModal();toast('Draft saved on this device')};$('#publish-audio').onclick=async()=>{if(!audioData)return toast('Record or import audio, then listen to it first');try{await send('/api/posts',{mediaData:audioData,mediaType:audioType,caption:$('#audio-caption').value});if(draft?.id)removeDraft(draft.id);closeModal();nav('home');await loadFeed();toast('Audio post shared')}catch(e){toast(e.message)}}}
function openProfileTabActions(){const p=$('.profile-banner');p.onclick=e=>{if(e.target.closest('.profile-settings'))return;if(!app.user)return;editCover()}}
async function bootstrap(){ensureExtraPages();wireFeedTabs();wireGestures();wirePageSwipe();activateLobbyGestures();$$('.nav-item').forEach(b=>b.onclick=()=>{const page=b.dataset.page==='search'?'explore':b.dataset.page;if(page==='profile')showProfile(app.user?.handle);else nav(page)});$('.notification-btn').onclick=()=>modal('Notifications',`<p>Notifications from your Trude friends will show up here.</p>`);$('#create-button').onclick=openCreateWheel;$('#create-button').addEventListener('pointerdown',()=>{app.createHold=setTimeout(openCreateWheel,350)});['pointerup','pointerleave','pointercancel'].forEach(e=>$('#create-button').addEventListener(e,()=>clearTimeout(app.createHold)));$('#close-wheel').onclick=()=>$('#create-wheel').classList.add('hidden');$('.wheel-backdrop').onclick=()=>$('#create-wheel').classList.add('hidden');$$('[data-create]').forEach(b=>b.onclick=()=>{$('#create-wheel').classList.add('hidden');openCreate(b.dataset.create)});$('#play-truth').onclick=playWithPeople;$$('.game-item').forEach(b=>b.onclick=playWithPeople);$('.edit-profile').onclick=()=>app.profile?editProfile(app.profile.profile):showProfile(app.user?.handle);$('.profile-tabs').addEventListener('click',e=>{const b=e.target.closest('[data-profile-tab]');if(b)loadProfileTab(b.dataset.profileTab)});$('#home-page').addEventListener('click',e=>{const b=e.target.closest('.feed-tab');if(b)return});
 if(localStorage.getItem('trude-data-saver')==='1')document.documentElement.classList.add('data-saver');try{const r=await api('/api/auth/me');app.user=r.user}catch{}updateProfile();await loadFeed();if(!app.user)openAuth('signup');
 if(location.hash.startsWith('#post/')){const id=location.hash.slice(6);setTimeout(()=>document.querySelector(`[data-post-id="${id}"]`)?.scrollIntoView(),200)}
}
async function joinRandom(){if(!requireLogin())return;try{const r=await api('/api/rooms');let room=r.rooms.find(x=>x.members<x.capacity);if(!room){const made=await send('/api/rooms',{title:'Random conversation · 30 min',capacity:20,duration:30});room={id:made.room}}await joinRoom(room.id)}catch(e){toast(e.message)}}
async function loadProfileTab(name){if(!app.profile)return;try{$$('[data-profile-tab]').forEach(b=>b.classList.toggle('chosen',b.dataset.profileTab===name));if(name==='Drafts')return renderDrafts();const r=await api(`/api/feed?tab=${encodeURIComponent(name)}`);app.profile.posts=r.posts;$('.profile-posts').innerHTML=r.posts.map(p=>`<button class="profile-tile" data-open-profile-post="${p.id}">${p.mediaUrl?`<img src="${p.mediaUrl}">`:`<span>✳</span><small>${esc(p.caption||p.body)}</small>`}</button>`).join('')||'<div class="empty-note"><span>✦</span><b>Nothing here yet</b><small>Content will appear here when it’s ready.</small></div>';$$('[data-open-profile-post]').forEach(b=>b.onclick=()=>{nav('home');loadFeed().then(()=>document.querySelector(`[data-post-id="${b.dataset.openProfilePost}"]`)?.scrollIntoView({behavior:'smooth'}))})}catch(e){toast(e.message)}}
async function toggleFollow(id,button){if(!requireLogin())return;try{const r=await send(`/api/profiles/${id}/follow`);button.classList.toggle('following',r.following);button.textContent=r.following?'Following':'Follow';if(app.profile&&app.profile.profile.id===id){app.profile.following=r.following;app.profile.counts.followers+=r.following?1:-1;renderProfile()}}catch(e){toast(e.message)}}
async function findGlobalPost(){const match=location.hash.match(/^#post\/(\d+)/);if(!match)return;const id=match[1];nav('home');await loadFeed();document.querySelector(`[data-post-id="${id}"]`)?.scrollIntoView({behavior:'smooth'});}
window.openHostLobby=openHostLobby;
function openAuth(mode='login'){
 const signup=mode==='signup',forgot=mode==='forgot';let stage=mode;
 const title=signup?'Create your account':forgot?'Reset your password':'Welcome back';
 const fields=signup?'<label>Your name<input name="name" required minlength="2" maxlength="40" placeholder="How friends know you"></label><label>Choose a handle<input name="handle" required minlength="3" maxlength="24" pattern="[A-Za-z0-9_.]+" placeholder="yourname"></label><label>Email or mobile number<input name="identifier" required autocomplete="username" placeholder="you@gmail.com or +1…"></label><label>Password<input name="password" required minlength="10" type="password" autocomplete="new-password" placeholder="At least 10 characters"></label><p class="auth-footnote">Test mode: email/SMS verification is off. Use test contact details only.</p>':forgot?'<p>Enter your account email or number. A local test code appears here because email/SMS delivery is not connected.</p><label>Email or mobile number<input name="identifier" required placeholder="Account email or number"></label>':'<label>Email or mobile number<input name="identifier" required autocomplete="username" placeholder="you@gmail.com or +1…"></label><label>Password<input name="password" required type="password" autocomplete="current-password" placeholder="Your password"></label><button type="button" class="text-btn forgot-trigger">Forgot password?</button>';
 const intro=signup?'A good place to make a little noise.':forgot?'We will help you get back into your account.':'Sign in and pick up where you left off.';
 const switchText=signup?'Already have an account?':forgot?'Remembered it?':'New to Trude?',switchAction=signup||forgot?'login':'signup',switchLabel=signup||forgot?'Sign in':'Create an account';
 modal(title,'<div class="auth-mark">t</div><p class="auth-lede">'+intro+'</p><form id="auth-form" class="auth-form">'+fields+'<div id="auth-error" class="form-error"></div><button class="modal-primary auth-submit" type="submit">'+(signup?'Create account':forgot?'Request reset':'Sign in')+'</button></form><button class="google-signin" type="button" data-auth="google"><span>G</span> Continue with Google</button><div class="auth-divider"><span>or</span></div><p class="auth-switch">'+switchText+' <button type="button" class="text-btn" data-auth="'+switchAction+'">'+switchLabel+'</button></p>');
 $('#auth-form').addEventListener('submit',async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(e.currentTarget).entries()),error=$('#auth-error');error.textContent='';try{
  if(stage==='forgot'){const r=await send('/api/auth/forgot',body);if(!r.resetCode){error.textContent=r.message;return}$('#auth-form').innerHTML='<input type="hidden" name="identifier" value="'+esc(body.identifier)+'"><div class="reset-code-display">Local test code <b>'+esc(r.resetCode)+'</b></div><label>Reset code<input name="code" inputmode="numeric" autocomplete="one-time-code" required maxlength="6"></label><label>New password<input name="password" type="password" required minlength="10" autocomplete="new-password"></label><div id="auth-error" class="form-error"></div><button class="modal-primary auth-submit">Save new password</button>';stage='reset';return}
  if(stage==='reset'){await send('/api/auth/reset',body);openAuth('login');toast('Password updated. Sign in again.');return}
  const result=await send('/api/auth/'+(signup?'signup':'login'),body);app.user=result.user;closeModal();updateProfile();await loadFeed();toast(signup?'Welcome to Trude ✳':'You are signed in');if(app.page==='lobby')loadLobbyDirectory();if(app.page==='chats')loadRooms()
 }catch(err){error.textContent=err.message}});
 $$('[data-auth]').forEach(b=>b.onclick=()=>b.dataset.auth==='google'?toast('Google sign-in needs a configured Trude OAuth client. Use an email or mobile test account.'):openAuth(b.dataset.auth));$('.forgot-trigger')?.addEventListener('click',()=>openAuth('forgot'));
}
window.openAuth=openAuth;
bootstrap().catch(e=>toast(e.message));
